"""PR-64: Node tags are consistent (`node_type`)."""

from __future__ import annotations

import pytest

from codeintel.runtime.runtime_bundle import RuntimeBundle

# Node suffixes generated by Hamilton decorators that don't need node_type tags
_HAMILTON_DECORATOR_SUFFIXES = (
    "_validator",  # From @check_output_custom
    "_raw",  # From various decorators
    "with_",  # From @pipe_input/@pipe_output macro-generated steps
)


def _is_hamilton_generated_node(node_name: str) -> bool:
    """Check if node is generated by Hamilton decorators.

    Hamilton decorators like @check_output_custom create additional nodes
    with specific suffixes. These don't need custom node_type tags.

    Parameters
    ----------
    node_name
        Name of the Hamilton node.

    Returns
    -------
    bool
        True if the node is generated by a Hamilton decorator.
    """
    return any(suffix in node_name for suffix in _HAMILTON_DECORATOR_SUFFIXES)


def _variable_name(variable: object) -> str:
    if isinstance(variable, str):
        return variable
    name = getattr(variable, "name", None)
    return str(name) if name is not None else str(variable)


def test_pr64_all_nodes_have_node_type_tag(hamilton_runtime: RuntimeBundle) -> None:
    """All Hamilton nodes should have a canonical node_type tag.

    Notes
    -----
    This test skips:
    - User-defined input nodes (node.user_defined = True)
    - Hamilton-generated decorator nodes (e.g., *_validator, *_raw)
    """
    missing: list[str] = []
    for variable in hamilton_runtime.dr.list_available_variables():
        node_name = _variable_name(variable)
        if getattr(variable, "user_defined", False):
            continue
        # Skip Hamilton-generated decorator nodes (Phase 1.5 validators, etc.)
        if _is_hamilton_generated_node(node_name):
            continue
        tags = getattr(variable, "tags", None)
        if not isinstance(tags, dict):
            missing.append(node_name)
            continue
        if isinstance(tags, dict) and tags.get("hamilton.data_saver") is True:
            continue
        node_type = tags.get("node_type")
        if not isinstance(node_type, str) or not node_type:
            missing.append(node_name)
        if "node_kind" in tags:
            missing.append(node_name)

    if missing:
        pytest.fail(f"Nodes missing canonical node_type tags: {sorted(set(missing))}")
